// Type definitions for intersystems-iris-native 1.0.0.
// Definitions by Jonathan Willeke.
// Definitions extended by Georgia Dimaki for intersystems-iris-native 1.3.0
// TODO: Version and name of nodejs sdk module


// https://stackoverflow.com/questions/34448251/typescript-add-a-method-on-a-class-from-another-module-populate-a-namespace

import {Decimal} from 'decimal.js';


/**
 * Definining basic types
 */

export type iris_decimal = Decimal;


/**
 * The type of most Iris method arguments.
 * SharedArrayBuffer, the type that results from slicing Buffer.buffer,
 * is purposely excluded; assert its type as Buffer if necessary:
 *
 *   b.buffer.slice(b.byteOffset, b.byteOffset+b.byteLength) as Buffer
 */
export type Scalar = boolean|number|bigint|string|null|Buffer|iris_decimal;
export type ScalarOrList = Scalar|IRISList;
export type IRISValue = Scalar|IRISList|IRISObject;
export type IRISReturnType = Scalar|IRISObject;
export type IRISArg = IRISValue|IRISReference;
export type IRISSubscript = Scalar|IRISList;


/**
 * The Native API connection object.
 *
 * This is declared as an interface, rather than a class, because there is no
 * usable constructor.  A Connection object is created by the module's
 * createConnection() method.
 */
export interface Connection {
    
    readonly host: string;
    readonly port: number;
    readonly namespace: string;
    readonly timeout: number;
    readonly sharedmemory: boolean;
    readonly logfile: string;
    readonly serverLocale: string;
    readonly protocolVersion: number;
    readonly compactDouble: boolean;
    
    close(): void;
    createIris(): Iris;
    isClosed(): boolean;
    isUsingSharedMemory(): boolean;
    toString(): string;
}

export class IRISGlobalNode implements Iterable<undefined> {
    constructor(globalName: string, ...subs: IRISSubscript[]);
    readonly size: number;

    clear(): void;
    delete(sub: IRISSubscript): boolean;
    entries(): GlobalIterator;
    forEach(callback: (err, enty: Scalar[]) => void, thisArg: any): void;
    get(sub: IRISSubscript, default_value?: any): Scalar|undefined;
    has(sub: IRISSubscript): boolean;
    keys(): GlobalIterator;
    subscripts: IRISGlobalNode["keys"]; // alias
    values(): GlobalIterator;
    node(): IRISGlobalNode;
    nodeEntries(): GlobalIterator;
    nodes(): GlobalIterator;
    reversed(): GlobalIterator;
    set(sub: IRISSubscript, value: ScalarOrList);
    [Symbol.iterator](): GlobalIterator;


}

export interface GlobalIterator extends IterableIterator<undefined> {
    entries(): GlobalIterator;
    keys(): GlobalIterator;
    reversed(): GlobalIterator;
    startFrom(sub: IRISSubscript): GlobalIterator;
    subscripts: GlobalIterator["keys"]; // alias
    nodes(): GlobalIterator;
    nodeEntries(): GlobalIterator;
    values(): GlobalIterator;
    [Symbol.iterator](): GlobalIterator;
    next(): { done: boolean, value?: any}
}


/**
 * The main Native API object.
 *
 * This is declared as an interface, rather than a class, because there is no
 * usable constructor.  An Iris object is created by a Connection object's
 * createIris() method.
 */
export interface Iris {
    // constructor(c?: Connection);
    getServerVersion(): string;
    getAPIVersion(): string;
    get(globalName: string, ...subs: IRISSubscript[]): null | IRISReturnType; // nullable for backward compatibility
    getObject: Iris["get"]; // alias
    getBoolean(globalName: string, ...subs: IRISSubscript[]): boolean;
    getBytes(globalName: string, ...subs: IRISSubscript[]): Buffer;
    getDecimal(globalName: string, ...subs: IRISSubscript[]): iris_decimal;
    getBigInt(globalName: string, ...subs: IRISSubscript[]): bigint;
    getNumber(globalName: string, ...subs: IRISSubscript[]): number;
    getString(globalName: string, ...subs: IRISSubscript[]): string;
    getList(globalName: string, ...subs: IRISSubscript[]): IRISList;
    getIRISList: Iris["getList"]; // alias
    set(value: ScalarOrList, globalName: string, ...subs: IRISSubscript[]): void;
    kill(globalName: string, ...subs: IRISSubscript[]): void;
    increment(value: number | iris_decimal, globalName: string, ...subs: IRISSubscript[]): number | iris_decimal;
    isDefined(globalName: string, ...subs: IRISSubscript[]): 0 | 1 | 10 | 11;
    nextSubscript(reversed: boolean, globalName: string, ...subs: IRISSubscript[]) : null|string;
    function(functionName: string, routineName: string, ...args: IRISArg[]): null|Scalar;
    functionObject: Iris["function"]; // alias
    functionBoolean(functionName: string, routineName: string, ...args: IRISArg[]): null|boolean;
    functionBytes(functionName: string, routineName: string, ...args: IRISArg[]): null|Buffer;
    functionDecimal(functionName: string, routineName: string, ...args: IRISArg[]): null|iris_decimal;
    functionBigInt(functionName: string, routineName: string, ...args: IRISArg[]): null|bigint;
    functionNumber(functionName: string, routineName: string, ...args: IRISArg[]): null|number;
    functionString(functionName: string, routineName: string, ...args: IRISArg[]): null|string;
    functionIRISList(functionName: string, routineName: string, ...args: IRISArg[]): null|IRISList;
    procedure(procedureName: string, routineName: string, ...args: IRISArg[]): void;
    classMethodValue(className: string, methodName: string, ...args: IRISArg[]): null|IRISReturnType;
    classMethodObject: Iris["classMethodValue"]; // alias
    classMethodBoolean(className: string, methodName: string, ...args: IRISArg[]): null|boolean;
    classMethodBytes(className: string, methodName: string, ...args: IRISArg[]): null|Buffer;
    classMethodDecimal(className: string, methodName: string, ...args: IRISArg[]): null|iris_decimal;
    classMethodBigInt(className: string, methodName: string, ...args: IRISArg[]): null|bigint;
    classMethodNumber(className: string, methodName: string, ...args: IRISArg[]): null|number;
    classMethodIRISList(className: string, methodName: string, ...args: IRISArg[]): IRISList; // non-null for backward compatibility
    classMethodString(className: string, methodName: string, ...args: IRISArg[]): null|string;
    classMethodVoid(className: string, methodName: string, ...args: IRISArg[]): void;
    lock(mode: string, seconds: number, name: string, ...subs: IRISSubscript[]): boolean;
    unlock(mode: string, name: string, ...subs: IRISSubscript[]): void;
    releaseAllLocks(): void;
    tStart(): void;        
    tCommit(): void;
    tRollback(): void;
    tRollbackOne(): void;
    getTLevel(): number;
    iterator(globalName: string, ...subs: IRISSubscript[]): GlobalIterator;
    node(globalName: string, ...subs: IRISSubscript[]): IRISGlobalNode;
    createList() : IRISList;
}

/**
 * Utility interface for the IRISList option construction parameter
 */
export interface IRISListOptions {
    locale?: string;
    isUnicode?: boolean;
    compactDouble?: boolean;
}

/**
 * The IRISList object.
 *
 * Unlike the Connection and Iris objects, an IRISList object is constructed
 * using the new keyword.  It can also be returned by an IRISList object's
 * getList() and getIRISList() methods, or by one of the following methods of an Iris object:
 * 
 * - classMethodIRISList()
 * - classMethodList()
 * - functionIRISList()
 * - functionList()
 * - getIRISList()
 * - getList()
 */
export class IRISList {
    constructor(value?: IRISList|Buffer);
    constructor(options: IRISListOptions);
    constructor(value: IRISList|Buffer, options?: IRISListOptions);
    readonly locale: string;
    readonly isUnicode: boolean;
    readonly compactDouble: boolean;
    add(value: ScalarOrList): IRISList;
    set(index: number, value: ScalarOrList): IRISList;
    get(index: number): Scalar;
    getBoolean(index: number): boolean;
    getBytes(index: number): Buffer;
    getDecimal(index: number): iris_decimal;
    getBigInt(index: number): bigint;
    getNumber(index: number): number;
    getList(index: number): IRISList;
    getIRISList: IRISList['getList']; // alias
    getString(index: number): string;
    remove(index: number): IRISList;
    clear(): IRISList;
    size(): number;
    count(): number;
	equals(list: any): boolean; // IRISList
    getBuffer(): Buffer;
    toString(): string;
}

export interface IRISObject {
    readonly connection: Connection;
    readonly oref: string;
    readonly closed: boolean;
    get: IRISObject['getObject']; // alias
    getObject(propertyName: string): null|IRISReturnType;
    getBoolean(propertyName: string): null|boolean;
    getBytes(propertyName: string): null|Buffer;
    getDecimal(propertyName: string): null|iris_decimal;
    getBigInt(propertyName: string): null|bigint;
    getNumber(propertyName: string): null|number;
    getIRISList(propertyName: string): null|IRISList;
    getString(propertyName: string): null|string;
    set(propertyName: string, propertyValue: IRISValue): void;
    invoke: IRISObject['invokeObject']; // alias
    invokeObject(methodName: string, ...args: IRISArg[]): null|IRISReturnType;
    invokeBoolean(methodName: string, ...args: IRISArg[]): null|boolean;
    invokeBytes(methodName: string, ...args: IRISArg[]): null|Buffer;
    invokeDecimal(methodName: string, ...args: IRISArg[]): null|iris_decimal;
    invokeBigInt(methodName: string, ...args: IRISArg[]): null|bigint;
    invokeNumber(methodName: string, ...args: IRISArg[]): null|number;
    invokeIRISList(methodName: string, ...args: IRISArg[]): IRISList; // non null to be similar to classMethodIRISList
    invokeString(methodName: string, ...args: IRISArg[]): null|string;
    invokeVoid(methodName: string, ...args: IRISArg[]): void;
    close(): void;
}

export namespace IRISReference {
    enum Type {
        ANY = 0,
        BOOLEAN,
        BYTES,
        DECIMAL,
        BIGINT,
        NUMBER,
        IRISLIST,
        STRING
    }
}

export class IRISReference {
    constructor(value: IRISValue, type?: IRISReference.Type);
    setValue(value: IRISValue): void;
    getValue(): null|IRISValue;
    setType(type: IRISReference.Type): void;
    getType(): IRISReference.Type;
    getObject: IRISReference["getValue"]; // alias
    getBoolean(): null|boolean;
    getBytes(): null|Buffer;
    getDecimal(): null|iris_decimal;
    getBigInt(): null|bigint;
    getNumber(): null|number;
    getString(): null|string;
    getIRISList(): null|IRISList;
}

export interface ConnectionInfo {
    host: string;
    port: number;
    ns: string;
    user: string;
    pwd: string;
    sharedmemory?: boolean;
    timeout?: number;
    logfile?: string;
    sslconfig?: string | boolean;
}

export function createConnection(connectionInfo: ConnectionInfo): Connection;
export function createConnection(connectionInfo: ConnectionInfo, callback: (err, c: Connection) => void): void;